def _graph_contract() -> dict[str, dict[str, object]]:
    items: dict[str, dict[str, object]] = {}
    for keys, formula, numerator, denominator, unit, time_basis, tables in _GRAPH_METHODS:
        for number in keys:
            key = f"g{number}"
            if any(key in group for group in GRAPH_GROUPS.values()):
                items[key] = {"formula": formula, "numerator": numerator,
                              "denominator": denominator, "unit": unit,
                              "time_basis": time_basis, "source_tables": tables}
    for key in (RECOVERY_FLOW_TABLE_KEY, RECOVERY_FLOW_MONTHS_KEY, RECOVERY_FLOW_DURATION_KEY, RECOVERY_FLOW_OUTCOMES_KEY):
        items[key] = {
            "formula": "Госпитализации с признаком койки пробуждения, сгруппированные по форме выбранного графика.",
            "numerator": "Госпитализации с recovery_bed_stay", "denominator": "Все госпитализации РАО",
            "unit": "случаев", "time_basis": "Дата госпитализации в [начало, конец).",
            "source_tables": ("admissions", "recovery_bed_stays", "events"),
        }
    return items


GRAPH_METRIC_METADATA = _graph_contract()

